CREATE TABLE IF NOT EXISTS market_items(id TEXT PRIMARY KEY, owner INTEGER NOT NULL, skin INTEGER NOT NULL CHECK(skin BETWEEN 0 AND 71), price INTEGER CHECK(price BETWEEN 1 AND 1000000), UNIQUE(owner,skin));
CREATE TABLE IF NOT EXISTS market_sales(id TEXT PRIMARY KEY, item TEXT NOT NULL, buyer INTEGER NOT NULL, seller INTEGER NOT NULL, skin INTEGER NOT NULL, price INTEGER NOT NULL, created INTEGER NOT NULL, seen INTEGER NOT NULL DEFAULT 0);
CREATE TRIGGER IF NOT EXISTS market_buy AFTER INSERT ON market_sales BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM market_items WHERE id=NEW.item AND owner=NEW.seller AND skin=NEW.skin AND price=NEW.price AND owner<>NEW.buyer) THEN RAISE(ABORT,'Listing unavailable') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM users WHERE id=NEW.buyer AND balance>=NEW.price) THEN RAISE(ABORT,'Insufficient coins') END;
 UPDATE users SET balance=balance-NEW.price WHERE id=NEW.buyer;
 UPDATE users SET balance=balance+NEW.price WHERE id=NEW.seller;
 UPDATE market_items SET owner=NEW.buyer,price=NULL WHERE id=NEW.item;
END;
CREATE TRIGGER IF NOT EXISTS market_shop BEFORE INSERT ON market_items BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM users WHERE id=NEW.owner AND balance>=CASE WHEN NEW.skin<6 THEN 150 WHEN NEW.skin<12 THEN 200 WHEN NEW.skin<18 THEN 250 WHEN NEW.skin<24 THEN 300 WHEN NEW.skin<30 THEN 400 ELSE 500 END) THEN RAISE(ABORT,'Insufficient coins') END;
 UPDATE users SET balance=balance-CASE WHEN NEW.skin<6 THEN 150 WHEN NEW.skin<12 THEN 200 WHEN NEW.skin<18 THEN 250 WHEN NEW.skin<24 THEN 300 WHEN NEW.skin<30 THEN 400 ELSE 500 END WHERE id=NEW.owner;
END;
